import{_ as n,c as t,o as a,ag as s}from"./chunks/framework.Ci10AEOF.js";const o="/docs-website/assets/channel_summary.BuAOSJYJ.png",r="/docs-website/assets/channel_destinations.CVdk9jUl.png",f=JSON.parse('{"title":"Channels","description":"The fundamental building blocks","frontmatter":{"title":"Channels","description":"The fundamental building blocks"},"headers":[],"relativePath":"engine/channels.md","filePath":"engine/channels.md","lastUpdated":1793057853000}'),i={name:"engine/channels.md"};function c(h,e,l,d,p,g){return a(),t("div",null,e[0]||(e[0]=[s(`<h1 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h1><p>A channel defines where data comes from and what is done with it.</p><h2 id="channel-lifecycle" tabindex="-1">Channel lifecycle <a class="header-anchor" href="#channel-lifecycle" aria-label="Permalink to &quot;Channel lifecycle&quot;">​</a></h2><p>You create and edit a channel in the channel editor. Your changes stay in the editor until you save. Saving stores the channel on the server. A saved channel does not process messages.</p><p>Deploying loads the saved channel into the engine. The scripts are compiled, the connectors are created, and <strong>Initial State</strong> decides whether the channel comes up started, paused, or stopped.</p><p>Start, pause, and stop apply to a deployed channel. Undeploying unloads it, and the saved channel stays on the server. Deleting removes the saved channel.</p><p><a href="./channel_state.html">Deploy, Start, and Channel State</a> has the detail.</p><h2 id="about-channels-and-connectors" tabindex="-1">About channels and connectors <a class="header-anchor" href="#about-channels-and-connectors" aria-label="Permalink to &quot;About channels and connectors&quot;">​</a></h2><p>A channel is made up of <strong>connectors</strong>. There are two kinds: a <strong>source connector</strong> brings data into the channel, and <strong>destination connectors</strong> usually send it on. Neither end has to be an external system. A Channel Reader receives messages from another channel. A Channel Writer sends messages to another channel. A JavaScript Writer runs a script, which need not send the message anywhere at all. Every channel has one source connector and one or more destinations. One channel can therefore receive an HL7 message over TCP, write it to a file, and insert selected fields into a database.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                          Channel                           │</span></span>
<span class="line"><span>│                                                            │</span></span>
<span class="line"><span>│  ┌────────────┐    ┌──────────────┐    ┌──────────────┐    │</span></span>
<span class="line"><span>│  │   Source   │───&gt;│   Filters    │───&gt;│ Destination  │    │</span></span>
<span class="line"><span>│  │ Connector  │    │ Transformers │    │ Connector(s) │    │</span></span>
<span class="line"><span>│  └────────────┘    └──────────────┘    └──────────────┘    │</span></span>
<span class="line"><span>│                                                            │</span></span>
<span class="line"><span>│  Scripts: Deploy | Preprocessor | Postprocessor | Undeploy │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>The filters and transformers are drawn once here for simplicity. Every connector, source and destination alike, has its own filter and transformer; see <a href="#connector-components">Connector components</a>.</p><h2 id="general-channel-properties" tabindex="-1">General channel properties <a class="header-anchor" href="#general-channel-properties" aria-label="Permalink to &quot;General channel properties&quot;">​</a></h2><p>These are configured on the Summary tab of the channel editor and cover the overall behavior of the channel. The Code Template Libraries, Library Resources and Deploy/Start Dependencies settings are on the tabs of the <strong>Channel Dependencies</strong> dialog, which opens from <strong>Set Dependencies</strong>:</p><ul><li><strong>Name and description</strong>. The channel&#39;s unique ID is assigned automatically, not entered</li><li><strong>Code Template Libraries</strong>. Controls which reusable JavaScript functions are accessible within the channel</li><li><strong>Library Resources</strong>. Specifies which custom Java classes can be referenced by the channel&#39;s connectors or scripts</li><li><strong>Deploy/Start Dependencies</strong>. Lets you define ordering relationships between channels so certain channels come online before others</li><li><strong>Attachment</strong>. Sets the channel&#39;s attachment handler, which pulls content out of the inbound message before the preprocessor and leaves a reference in its place. The attachment is stored once, apart from the copies of content kept for each connector message. See <a href="./message_lifecycle.html#attachments">Attachments</a></li><li><strong>Message Storage</strong>. Governs what message data gets persisted, whether encryption is applied, and whether connectors can use persistent queuing</li><li><strong>Message Pruning</strong>. Defines retention periods for message data with an option to archive messages to disk before they are removed</li><li><strong>Custom Metadata</strong>. Lets you pull specific values out of messages and store them as searchable columns in the Message Browser</li><li><strong>Tags</strong>. Labels for organizing channels into logical groups</li></ul><p><img src="`+o+'" alt="The channel editor&#39;s Summary tab, with the Channel Properties, Message Storage, Message Pruning, Custom Metadata and Channel Description panels"></p><h2 id="source-connector" tabindex="-1">Source connector <a class="header-anchor" href="#source-connector" aria-label="Permalink to &quot;Source connector&quot;">​</a></h2><p>Each channel has exactly one source connector responsible for bringing data into OIE. Beyond the standard filter and transformer components, source connectors offer several additional features:</p><ul><li><strong>Source Queue</strong>. Sets when the source connector responds. When it is off, the source connector responds once the message has gone through the channel, with whatever the <strong>Response</strong> setting picks. When it is on, the source connector stores the message, puts it on the source queue and responds straight away, and a source queue thread processes the message later. <strong>Response</strong> can then only be None or Auto-generate (Before processing). For example, an HL7 sender on a TCP Listener with the source queue on gets its ACK as soon as the message is stored. If a destination fails afterwards, the sender has already been told the message was accepted. See <a href="./queueing.html">Queueing</a>.</li><li><strong>Process Batch</strong>. When set to Yes, a single inbound payload gets broken apart into individual messages, each of which travels through the channel independently.</li><li><strong>Response</strong>. Configures what gets sent back to the system that delivered the message. Options include auto-generating a response based on the source data type, forwarding the reply from a particular destination, or providing an entirely custom response.</li><li><strong>Max Processing Threads</strong>. Defaults to 1, meaning messages go through the channel one at a time. Above 1, messages are processed in parallel and their order is not guaranteed. This setting does not affect asynchronous processes such as destination queuing.</li></ul><h2 id="destination-connectors" tabindex="-1">Destination connectors <a class="header-anchor" href="#destination-connectors" aria-label="Permalink to &quot;Destination connectors&quot;">​</a></h2><p>A channel has at least one destination connector, and at least one of them has to be enabled. A script anywhere in the channel can also send data out, and a script on the source side does so before any destination is reached.</p><p><img src="'+r+`" alt="The channel editor&#39;s Destinations tab, listing two destinations with their connector types and chain numbers above the selected destination&#39;s settings"></p><p>A message can reach none, some, or all of a channel&#39;s destinations. The <a href="./glossary.html#destination-set">destination set</a> decides which ones it goes to, and each destination&#39;s own filter can still filter it out. Destinations have a few features beyond the standard filter and transformer:</p><ul><li><strong>Enabled</strong>. Whether the destination takes part in processing. A disabled one is skipped entirely.</li><li><strong>Wait for previous destination</strong>. Determines which <strong>chain</strong> the destination belongs to (see <a href="#destination-chains">Destination Chains</a> below).</li><li><strong>Response Transformer</strong>. A second transformer that runs on what the destination got back. It has its own inbound and outbound data types. Its steps can do anything a transformer step can, and it can also set the response&#39;s status, status message, and error message. It runs when the response message is not empty, so a destination that failed to connect skips it. When the response inbound data type is <strong>Raw</strong>, it runs either way.</li></ul><h2 id="channel-scripts" tabindex="-1">Channel scripts <a class="header-anchor" href="#channel-scripts" aria-label="Permalink to &quot;Channel scripts&quot;">​</a></h2><p>Each channel has four configurable scripts that run at specific points in the lifecycle:</p><table tabindex="0"><thead><tr><th>Script</th><th>When It Runs</th></tr></thead><tbody><tr><td><strong>Deploy Script</strong></td><td>Runs once while the channel deploys, before it starts. If it throws, the deploy fails</td></tr><tr><td><strong>Preprocessor Script</strong></td><td>Fires for each message, after the source connector receives it and after any attachment extraction, but before filtering and transformation begin. It can modify the raw message, for example to strip a byte order mark (BOM) from the front before the engine parses it.</td></tr><tr><td><strong>Postprocessor Script</strong></td><td>Fires for each message after the source and all destinations have finished (not counting asynchronous queue processing). With the source queue off, that is before the source connector sends its response. Has access to destination responses and can return a custom reply for the source to use.</td></tr><tr><td><strong>Undeploy Script</strong></td><td>Runs once while the channel undeploys, after it has stopped</td></tr></tbody></table><h2 id="connector-components" tabindex="-1">Connector components <a class="header-anchor" href="#connector-components" aria-label="Permalink to &quot;Connector components&quot;">​</a></h2><p>Every connector, whether source or destination, shares a common set of building blocks:</p><h3 id="general-connector-properties" tabindex="-1">General connector properties <a class="header-anchor" href="#general-connector-properties" aria-label="Permalink to &quot;General connector properties&quot;">​</a></h3><p>Each connector is identified by a name and a <strong>metadata ID</strong>. The source connector is always named &quot;Source&quot; with a metadata ID of 0. Destination connectors have user-defined names and metadata IDs that start at 1 and increment from there. Renaming a destination does not change its metadata ID.</p><h3 id="connector-specific-properties" tabindex="-1">Connector-specific properties <a class="header-anchor" href="#connector-specific-properties" aria-label="Permalink to &quot;Connector-specific properties&quot;">​</a></h3><p>The configuration fields vary by connector type. See <a href="./connector_reference_sources.html">Source Connectors</a> and <a href="./connector_reference_destinations.html">Destination Connectors</a> for specifics.</p><h3 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h3><p>A filter decides whether a message goes on. Whatever you build in the filter editor becomes JavaScript, and the <strong>Generated Script</strong> tab shows what it built. The script must return true or false.</p><p>A filter rule can also run any code a transformer step can. It can set a map variable, reshape the message, or call a code template.</p><p>See <a href="./filters_and_transformers.html">Filters and Transformers</a> for details.</p><h3 id="transformer" tabindex="-1">Transformer <a class="header-anchor" href="#transformer" aria-label="Permalink to &quot;Transformer&quot;">​</a></h3><p>A transformer is a list of steps that run on the message. They usually modify it, convert it between formats, or pull out values for later steps. Every transformer has an <strong>inbound data type</strong> and an <strong>outbound data type</strong>, which the engine uses to serialize the message on the way in and deserialize it on the way out. See <a href="./filters_and_transformers.html">Filters and Transformers</a> for details.</p><h2 id="destination-chains" tabindex="-1">Destination chains <a class="header-anchor" href="#destination-chains" aria-label="Permalink to &quot;Destination chains&quot;">​</a></h2><p>Chains are a byproduct of the <strong>Wait for previous destination</strong> checkbox on each destination.</p><p>It sits on the <strong>Destinations</strong> tab beside the connector type dropdown, and applies to the destination selected in the table above it. If it is checked, the destination joins the chain of the destination above it. If it is cleared, the destination starts a new chain. On the first destination it is cleared and greyed out, because the first destination always starts the first chain.</p><p>Chains run concurrently. Within a chain, destinations run one at a time, in order.</p><p>The engine builds the chains when the channel deploys, reading the destination list from top to bottom and skipping disabled destinations. Reordering the list changes the chains. So does disabling a destination: disable the one that starts a chain and the destinations below it join the chain above.</p><p>For example, with 5 destinations where Destination 3 does not wait on Destination 2 (starting a new chain):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source Connector</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>   Preprocessor</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>  ┌────┴────┐</span></span>
<span class="line"><span>  │         │</span></span>
<span class="line"><span>Chain 1   Chain 2</span></span>
<span class="line"><span>  │         │</span></span>
<span class="line"><span>Dest 1    Dest 3</span></span>
<span class="line"><span>  │         │</span></span>
<span class="line"><span>Dest 2    Dest 4</span></span>
<span class="line"><span>  │         │</span></span>
<span class="line"><span>  │       Dest 5</span></span>
<span class="line"><span>  │         │</span></span>
<span class="line"><span>  └────┬────┘</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>  Postprocessor</span></span></code></pre></div><p>Here, Chain 1 (Dest 1 and 2) and Chain 2 (Dest 3, 4, and 5) run concurrently. If each destination takes 1 second, total processing time is 3 seconds (the longer chain) rather than 5. The source connector&#39;s filter and transformer, which run after the preprocessor and before the chains start, are left out of the diagram.</p><h2 id="channel-groups" tabindex="-1">Channel groups <a class="header-anchor" href="#channel-groups" aria-label="Permalink to &quot;Channel groups&quot;">​</a></h2><p>Channels can be organized into <strong>groups</strong>. Groups have no effect on processing behavior.</p><ul><li>Create groups in the Channels panel</li><li>Drag and drop channels between groups</li><li>Deploy a whole group at once from the Channels view; to undeploy, select its channels on the Dashboard</li></ul><h2 id="channel-states" tabindex="-1">Channel states <a class="header-anchor" href="#channel-states" aria-label="Permalink to &quot;Channel states&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Description</th></tr></thead><tbody><tr><td><strong>Started</strong></td><td>Channel is actively processing messages</td></tr><tr><td><strong>Stopped</strong></td><td>Channel is deployed but not processing</td></tr><tr><td><strong>Paused</strong></td><td>Channel is deployed, source is paused (queued messages still process)</td></tr><tr><td><strong>Undeployed</strong></td><td>Saved on the server, not loaded in the engine</td></tr></tbody></table><p>This table lists the states a channel rests in. The Dashboard also shows transitional states while a channel changes state. See <a href="./channel_state.html#states">Deploy, Start, and Channel State</a> for the full list.</p><h2 id="connector-types" tabindex="-1">Connector types <a class="header-anchor" href="#connector-types" aria-label="Permalink to &quot;Connector types&quot;">​</a></h2><p>See <a href="./connector_reference_sources.html">Source Connectors</a> and <a href="./connector_reference_destinations.html">Destination Connectors</a> for every type and every setting it exposes.</p><p>Additional connectors are available as community extensions, cataloged at <a href="https://openintegrationengine.org/plugins/" target="_blank" rel="noreferrer">openintegrationengine.org/plugins</a>. See the <a href="./plugins.html">Plugin Guide</a> for installing them.</p>`,55)]))}const m=n(i,[["render",c]]);export{f as __pageData,m as default};
